import{_ as t,C as o,o as r,c as i,ag as c,E as s}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"仕様","description":"","frontmatter":{},"headers":[],"relativePath":"ja/spec/index.md","filePath":"ja/spec/index.md"}'),d={name:"ja/spec/index.md"};function n(l,e,m,h,p,f){const a=o("StatusNote");return r(),i("div",null,[e[0]||(e[0]=c('<h1 id="仕様" tabindex="-1">仕様 <a class="header-anchor" href="#仕様" aria-label="Permalink to &quot;仕様&quot;">​</a></h1><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><p>exact な <strong>FormRef</strong> は、API group・kind・definition version・schema digest の 組み合わせです。互換性は kind 名だけから推測しません — epoch が違えば別の契約です。 Form group は <a href="/spec/form-families.html">Form Families</a> で namespace 化され、 Host API group はどの Form group からも独立した protocol 互換性 identity です。</p><table tabindex="0"><thead><tr><th>Surface</th><th>Identity</th></tr></thead><tbody><tr><td>現在の Form Family</td><td><code>edge.forms.takoform.com/v1beta1</code> (Beta family; Experimental <code>0.1.0</code> 15種)</td></tr><tr><td>現在の Host API wire</td><td><code>forms.takoform.com/v1beta1</code> (discovery は <code>/.well-known/takoform/v1beta1</code>)</td></tr><tr><td>現在の package envelope</td><td><code>packages.forms.takoform.com/v1alpha4</code></td></tr><tr><td>Provider distribution</td><td><code>v2.1.1</code> Registry 公開済みの current stable distribution（descriptor は owner 公開後も <code>candidate-only</code> metadata）。<code>v2.0.0</code> と <code>v1.0.3</code> は撤回された epoch の不変の Registry 履歴</td></tr></tbody></table><p>pre-Beta の epoch（<code>forms.takoform.com/v1alpha1</code> と <code>/v1alpha2</code>）は撤回されました (<a href="/spec/decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>)。 identity は公開台帳に retired として記録され、バイト列はリポジトリ履歴に残ります。 provider の SemVer はどの API identity からも独立しています。</p><h2 id="現在レーンの契約-英語のみ" tabindex="-1">現在レーンの契約 (英語のみ) <a class="header-anchor" href="#現在レーンの契約-英語のみ" aria-label="Permalink to &quot;現在レーンの契約 (英語のみ)&quot;">​</a></h2><ul><li><a href="/spec/form-families.html">Form Families</a> — namespace 化された Form group と Edge Platform Family</li><li><a href="/spec/host-api/v1beta1.html">Host API v1beta1</a> — uid/generation/revision 識別・long-running operation・fencing</li><li><a href="/spec/interface-contract/">Interface contracts</a> — Form のサービスが公開する exact な capability 契約</li><li><a href="/spec/binding-contract/">Binding contracts</a> — revision が保持する typed な capability 利用</li><li><a href="/spec/artifact-transport/">Artifact transport</a> — content-addressed な artifact upload と manifest</li></ul><h2 id="normative-schemas" tabindex="-1">Normative schemas <a class="header-anchor" href="#normative-schemas" aria-label="Permalink to &quot;Normative schemas&quot;">​</a></h2><p><code>forms.takoform.com/schemas/...</code> で公開しています。現在の Beta identity:</p><ul><li><a href="/schemas/v1beta1/form-ref.schema.json">form-ref v1beta1</a></li><li><a href="/schemas/v1beta1/form-definition.schema.json">form-definition v1beta1</a></li><li><a href="/schemas/v1beta1/host-api-wire.schema.json">host-api-wire v1beta1</a></li><li><a href="/schemas/v1alpha4/package-index.schema.json">package-index v1alpha4</a></li></ul><p>撤回された epoch の schema identity は <a href="/release/public-schema-identities.json"><code>release/public-schema-identities.json</code></a> に retired として記録され、再利用されません。</p><h2 id="ライフサイクル" tabindex="-1">ライフサイクル <a class="header-anchor" href="#ライフサイクル" aria-label="Permalink to &quot;ライフサイクル&quot;">​</a></h2><p>Form は Proposal → Experimental → Stable → Legacy の順に進みます。成熟度は、 独立した実装と証拠から獲得されるもので、公開された事実や人気から来るものでは ありません。新しい Form は必ず先行事例 (OCCI、CIMI、TOSCA、Kubernetes/Crossplane、 provider ネイティブのリソース) から検討を始めます。</p>',13)),s(a)])}const v=t(d,[["render",n]]);export{u as __pageData,v as default};
